		ie.NewSourceInterface(ie.SrcInterfaceAccess),
		ie.NewNetworkInstance(dnn),
	)

	createPDR := ie.NewCreatePDR(
		ie.NewPDRID(1),
		ie.NewPrecedence(200),
		pdi,
		ie.NewFARID(1),
	)

