	//   - IPv4: has1stBit(0x02) = false, has3rdBit(0x02) = false, has5thBit(0x02) = false ✗
	//   - IPv6: has2ndBit(0x02) = true ✓
	// - This creates an OuterHeaderCreation with TEID and IPv6, but NO IPv4
	// - When UPF calls ip2int(ohcFields.IPv4Address), IPv4Address is nil -> panic
	// - Even though UPF uses go-pfcp library, parsing this will result in IPv4Address = nil
	outerHeaderIE := ie.NewOuterHeaderCreation(0x0200, 100, "", "2001:db8::1", 0, 0, 0)
	if outerHeaderIE == nil {
		return errors.New("failed to craft OuterHeaderCreation IE")
	}

